  useEffect(() => { setEditData({ housekeeper_id: record.housekeeper_id || '', report: record.report || '', notes: record.notes || '' }) }, [record])
  const handleSaveEdit = async () => { setSaving(true); try { const sel = housekeepers.find(h => h.id === editData.housekeeper_id); await supabase.from('housekeeping_records').update({ housekeeper_id: editData.housekeeper_id || null, housekeeper_code: sel?.code || null, report: editData.report, notes: editData.notes, updated_at: new Date().toISOString() }).eq('id', record.id); toast.success('Updated'); setIsEditing(false); onUpdate() } catch { toast.error('Failed') } finally { setSaving(false) } }
