        <div className="flex-1 min-w-0 px-2">{linkedBooking ? <span className="font-semibold text-gray-700 dark:text-gray-300 text-sm font-mono">{linkedBooking.booking_code || '—'}</span> : <span className="text-xs text-gray-400 italic">Deep Clean</span>}</div>
